export const getCompareAdminAiPromptVersionsUrl = (type: 'daily' | 'monthly' | 'geo',
    params: CompareAdminAiPromptVersionsParams,) => {
  const normalizedParams = new URLSearchParams();

  Object.entries(params || {}).forEach(([key, value]) => {

    if (value !== undefined) {
      normalizedParams.append(key, value === null ? 'null' : String(value))
    }
  });

  const stringifiedParams = normalizedParams.toString();

  return stringifiedParams.length > 0 ? `/api/admin/ai/prompts/${type}/compare?${stringifiedParams}` : `/api/admin/ai/prompts/${type}/compare`
}

